unsafe {
    let mut row_info: png_row_info = png_row_info {
        width: 0,
        rowbytes: 0,
        color_type: 0,
        bit_depth: 0,
        channels: 0,
        pixel_depth: 0,
    };
    if png_ptr.is_null() {
        return;
    }

    let png = &mut *png_ptr;

    if png.flags as c_uint & PNG_FLAG_ROW_INIT == 0 as c_uint {
        png_read_start_row(png_ptr);
    }

    row_info.width = png.iwidth;
    row_info.color_type = png.color_type;
    row_info.bit_depth = png.bit_depth;
    row_info.channels = png.channels;
    row_info.pixel_depth = png.pixel_depth;
    row_info.rowbytes = if row_info.pixel_depth as c_int >= 8 as c_int {
        (row_info.width as png_size_t)
            .wrapping_mul(row_info.pixel_depth as png_size_t >> 3 as c_int)
    } else {
        (row_info.width as png_size_t)
            .wrapping_mul(row_info.pixel_depth as png_size_t)
            .wrapping_add(7 as png_size_t)
            >> 3 as c_int
    };

    png.row_number == 0 as c_uint && png.pass as c_int == 0 as c_int;

    if png.interlaced as c_int != 0 as c_int
        && png.transformations as c_uint & PNG_INTERLACE != 0 as c_uint
    {
        match png.pass as c_int {
            0 => {
                if png.row_number as c_uint & 0x7 as c_uint != 0 {
                    if !dsp_row.is_null() {
                        png_combine_row(png_ptr, dsp_row, 1 as c_int);
                    }
                    png_read_finish_row(png_ptr);
                    return;
                }
            }
            1 => {
                if png.row_number as c_uint & 0x7 as c_uint != 0
                    || png.width < 5 as c_uint
                {
                    if !dsp_row.is_null() {
                        png_combine_row(png_ptr, dsp_row, 1 as c_int);
                    }
                    png_read_finish_row(png_ptr);
                    return;
                }
            }
            2 => {
                if png.row_number as c_uint & 0x7 as c_uint != 4 as c_uint {
                    if !dsp_row.is_null() && png.row_number as c_uint & 4 as c_uint != 0 {
                        png_combine_row(png_ptr, dsp_row, 1 as c_int);
                    }
                    png_read_finish_row(png_ptr);
                    return;
                }
            }
            3 => {
                if png.row_number as c_uint & 3 as c_uint != 0
                    || png.width < 3 as c_uint
                {
                    if !dsp_row.is_null() {
                        png_combine_row(png_ptr, dsp_row, 1 as c_int);
                    }
                    png_read_finish_row(png_ptr);
                    return;
                }
            }
            4 => {
                if png.row_number as c_uint & 3 as c_uint != 2 as c_uint {
                    if !dsp_row.is_null() && png.row_number as c_uint & 2 as c_uint != 0 {
                        png_combine_row(png_ptr, dsp_row, 1 as c_int);
                    }
                    png_read_finish_row(png_ptr);
                    return;
                }
            }
            5 => {
                if png.row_number as c_uint & 1 as c_uint != 0
                    || png.width < 2 as c_uint
                {
                    if !dsp_row.is_null() {
                        png_combine_row(png_ptr, dsp_row, 1 as c_int);
                    }
                    png_read_finish_row(png_ptr);
                    return;
                }
            }
            6 | _ => {
                if png.row_number as c_uint & 1 as c_uint == 0 as c_uint {
                    png_read_finish_row(png_ptr);
                    return;
                }
            }
        }
    }

    if png.mode as c_uint & PNG_HAVE_IDAT == 0 as c_uint {
        png_error(
            png_ptr,
            b"Invalid attempt to read row data\0" as *const u8 as png_const_charp,
        );
    }

    let row_buf = png.row_buf;
    let prev_row = png.prev_row;
    let row_buf_len = (row_info.rowbytes as usize).wrapping_add(1);

    *row_buf = 255 as png_byte;
    png_read_IDAT_data(
        png_ptr,
        row_buf,
        (row_info.rowbytes as png_alloc_size_t).wrapping_add(1 as png_alloc_size_t),
    );

    let filter = *row_buf as c_int;
    if filter > PNG_FILTER_VALUE_NONE {
        if filter < PNG_FILTER_VALUE_LAST {
            png_read_filter_row(
                png_ptr,
                &raw mut row_info,
                row_buf.offset(1),
                prev_row.offset(1) as png_const_bytep,
                filter,
            );
        } else {
            png_error(
                png_ptr,
                b"bad adaptive filter value\0" as *const u8 as png_const_charp,
            );
        }
    }

    // SAFETY: row_buf and prev_row are valid for rowbytes + 1 bytes here, and the
    // original code used memcpy, so these regions are required to be non-overlapping.
    core::ptr::copy_nonoverlapping(row_buf, prev_row, row_buf_len);

    if png.transformations != 0 {
        png_do_read_transformations(png_ptr, &raw mut row_info);
    }

    if png.transformed_pixel_depth as c_int == 0 as c_int {
        png.transformed_pixel_depth = row_info.pixel_depth;
        if row_info.pixel_depth as c_int > png.maximum_pixel_depth as c_int {
            png_error(
                png_ptr,
                b"sequential row overflow\0" as *const u8 as png_const_charp,
            );
        }
    } else if png.transformed_pixel_depth as c_int != row_info.pixel_depth as c_int {
        png_error(
            png_ptr,
            b"internal sequential row size calculation error\0" as *const u8
                as png_const_charp,
        );
    }

    if png.interlaced as c_int != 0 as c_int
        && png.transformations as c_uint & PNG_INTERLACE != 0 as c_uint
    {
        if (png.pass as c_int) < 6 as c_int {
            png_do_read_interlace(
                &raw mut row_info,
                row_buf.offset(1),
                png.pass as c_int,
                png.transformations,
            );
        }
        if !dsp_row.is_null() {
            png_combine_row(png_ptr, dsp_row, 1 as c_int);
        }
        if !row.is_null() {
            png_combine_row(png_ptr, row, 0 as c_int);
        }
    } else {
        if !row.is_null() {
            png_combine_row(png_ptr, row, -(1 as c_int));
        }
        if !dsp_row.is_null() {
            png_combine_row(png_ptr, dsp_row, -(1 as c_int));
        }
    }

    png_read_finish_row(png_ptr);
    if png.read_row_fn.is_some() {
        Some(png.read_row_fn.expect("non-null function pointer"))
            .expect("non-null function pointer")(
            png_ptr as png_structp,
            png.row_number,
            png.pass as c_int,
        );
    }
}

